package com.cpf.starter.tcp;import java.time.Instant;import java.util.*;public final class CpfTcpOperations {private final CpfTcpUnknownResultStore unknown;private final CpfTcpCorrelationRegistry correlations;private final List<Audit> audit=Collections.synchronizedList(new ArrayList<>());public CpfTcpOperations(CpfTcpUnknownResultStore u,CpfTcpCorrelationRegistry c){unknown=u;correlations=c;}public Snapshot snapshot(){return new Snapshot(correlations.pendingCount(),correlations.orphans().size(),unknown.snapshot().size());}public boolean reconcile(String correlationId,String operator,String reason){if(operator==null||operator.isBlank()||reason==null||reason.isBlank())throw new SecurityException("operator and reason required");boolean result=unknown.reconcile(correlationId);audit.add(new Audit(correlationId,operator,reason,result,Instant.now()));return result;}public List<Audit> audit(){synchronized(audit){return List.copyOf(audit);}}public record Snapshot(int pending,int orphan,int unknownResult){}public record Audit(String correlationId,String operator,String reason,boolean reconciled,Instant at){} }
